(()=>{'use strict';
 const menu=document.querySelector('.nx-mobile-menu');if(menu){const close=()=>{menu.open=false;};menu.addEventListener('click',event=>{if(event.target.closest('a'))close();});document.addEventListener('click',event=>{if(!menu.contains(event.target))close();});document.addEventListener('keydown',event=>{if(event.key==='Escape'&&menu.open){close();menu.querySelector('summary').focus();}});matchMedia('(min-width:901px)').addEventListener('change',close);}
 const dialog=document.querySelector('.nx-search-dialog'),input=document.querySelector('#nx-guide-search'),results=document.querySelector('#nx-search-results'),count=document.querySelector('#nx-search-count');
 if(dialog&&input){const render=()=>{const q=input.value.trim().toLowerCase();results.replaceChildren();if(!q){count.textContent='Search our practical guides.';return;}const found=(window.NX_GUIDES||[]).filter(g=>(g.title+' '+g.description+' '+g.category).toLowerCase().includes(q));count.textContent=found.length?found.length+' guides found'+(found.length>12?' · first 12 shown':'')+'.':'No match. Try a model name or a broader topic.';for(const guide of found.slice(0,12)){const li=document.createElement('li'),a=document.createElement('a'),cat=document.createElement('span');a.href=guide.url;cat.textContent=guide.category==='gear'?'Desk & tech':guide.category==='apparel'?'Style':guide.category;a.append(cat,document.createTextNode(guide.title));li.append(a);results.append(li);}};document.querySelector('.nx-search-open')?.addEventListener('click',()=>{dialog.showModal();input.focus();});document.querySelector('.nx-search-close')?.addEventListener('click',()=>dialog.close());input.addEventListener('input',render);dialog.addEventListener('click',event=>{if(event.target===dialog){const rect=dialog.getBoundingClientRect();if(event.clientX<rect.left||event.clientX>rect.right||event.clientY<rect.top||event.clientY>rect.bottom)dialog.close();}});}
 // Retain the existing collection event handler where it is already installed.
 if(!document.querySelector('script[src*="/assets/picks.js"]'))document.addEventListener('click',event=>{const a=event.target.closest('a[data-affiliate]');if(a&&typeof window.gtag==='function')window.gtag('event','affiliate_click',{product_id:a.dataset.affiliate,category:a.dataset.category,location:location.pathname==='/'?'home':'guide',transport_type:'beacon'});});
 document.querySelectorAll('a[href^="#source-"]').forEach(a=>a.addEventListener('click',()=>{const target=document.getElementById(a.hash.slice(1));const details=target?.closest('details');if(details)details.open=true;}));
})();
